import{_,C as t,c as p,o as x,j as i,G as e,a as m}from"./chunks/framework.B63Sb1io.js";const W=JSON.parse('{"title":"ISO/OSI 参考模型和 TCP/IP 参考模型","titleTemplate":"408计算机网络","description":"综述","frontmatter":{"title":"ISO/OSI 参考模型和 TCP/IP 参考模型","titleTemplate":"408计算机网络","description":"综述","layout":"doc","navbar":true,"sidebar":true,"aside":false,"outline":"deep","lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/408/408_CN/01/408_CN_11.md","filePath":"post/kaoyan/408/408_CN/01/408_CN_11.md","lastUpdated":1756612082000}'),I={name:"post/kaoyan/408/408_CN/01/408_CN_11.md"};function g(s,n,r,l,d,c){const o=t("QuizControls"),a=t("QuizChoice");return x(),p("div",null,[n[0]||(n[0]=i("h1",{id:"_1-2-习题-——-计算机网络的体系结构与参考模型",tabindex:"-1"},[m("1.2 习题 —— 计算机网络的体系结构与参考模型 "),i("a",{class:"header-anchor",href:"#_1-2-习题-——-计算机网络的体系结构与参考模型","aria-label":'Permalink to "1.2 习题 —— 计算机网络的体系结构与参考模型"'},"​")],-1)),n[1]||(n[1]=i("br",null,null,-1)),e(o),e(a,{question:"**01.** 下列选项中，**不属于**对网络模型进行分层的目标的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["提供标准语言","定义功能执行的方法","定义标准界面","增加功能之间的独立性"],correctAnswer:1,explanation:"分层属于计算机网络体系结构的范畴，选项 A、C 和 D 均是网络模型分层的目的，而分层的目的不包括定义功能执行的具体方法。"}),e(a,{question:"**02.** 将用户数据分成一个个数据块传输的优点不包括 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["减少延迟时间","提高错误控制效率","使多个应用更公平地使用共享通信介质","有效数据在协议数据单元（PDU）中所占比例更大"],correctAnswer:3,explanation:"将用户数据分成一个个数据块传输，因为每块均需加入控制信息，所以实际上会使有效数据在 PDU 中所占的比例更小。其他各项均为其优点。"}),e(a,{question:"**03.** 协议是指在 _______ 之间进行通信的规则或约定。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["同一节点的上下层","不同节点","相邻实体","不同节点对等实体"],correctAnswer:3,explanation:"协议是为对等层实体之间进行逻辑通信而定义的规则的集合。"}),e(a,{question:"**04.** OSI 参考模型中的实体指的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["实现各层功能的规则","上下层之间进行交互时所要的信息","各层中实现该层功能的软件或硬件","同一节点中相邻两层相互作用的地方"],correctAnswer:2,explanation:"实体是指每一层中实现该层功能的软件或硬件，可以是程序、模块、子程序或设备。"}),e(a,{question:"**05.** 在 OSI 参考模型中，第 n 层与它之上的第 n+1 层的关系是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["第 n 层为第 n+1 层提供服务","第 n+1 层为从第 n 层接收的报文添加一个报头","第 n 层使用第 n+1 层提供的服务","第 n 层和第 n+1 层相互没有影响"],correctAnswer:0,explanation:""}),e(a,{question:"**06.** 下列关于计算机网络及其结构模型的说法中，错误的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["世界上第一个计算机网络是 ARPAnet","Internet 最早起源于 ARPAnet","国际标准化组织（ISO）设计出了 OSI/RM 参考模型，即实际执行的标准","TCP/IP 模型分为 4 个层次"],correctAnswer:2,explanation:"ISO 设计了开放系统互连参考模型（OSI/RM），但实际执行的通用标准是 TCP/IP 标准。"}),e(a,{question:"**07.** _______ 是计算机网络中 OSI 参考模型的 3 个主要概念。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["服务、接口、协议","结构、模型、交换","子网、层次、端口","广域网、城域网、局域网"],correctAnswer:0,explanation:"OSI参考模型的三个主要概念是：服务、接口、协议。服务定义了该层为上层提供什么功能；接口定义了上层如何使用下层的服务；协议定义了该层实体如何实现服务的规则。这三个概念是理解分层模型的关键。"}),e(a,{question:"**08.** 下列关于网络协议三要素的描述中，正确的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["数据格式、编码、信号电平","数据格式、控制信息、速度匹配","语法、语义、同步","编码、控制信息、同步"],correctAnswer:2,explanation:"网络协议的三要素是语法、语义和同步（时序）。语法定义了数据的结构和格式；语义定义了数据的含义和解释；同步定义了事件发生的顺序和时序关系。"}),e(a,{question:"**09.** 释放 TCP 连接的四次挥手报文的先后关系，属于网络协议三要素中的 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["语法","时序","语义","服务"],correctAnswer:1,explanation:"释放TCP连接的四次挥手报文的先后关系属于网络协议三要素中的时序（同步）。时序定义了事件发生的顺序和时间关系，四次挥手必须按照特定的顺序进行：FIN→ACK→FIN→ACK。"}),e(a,{question:"**10.** 下图是 TCP 报文段的首部格式，它描述的是网络协议三要素中的 _______ 。",image:"/img/png/408_CN/22.png",imageWidth:"600px",explanationImage:"",explanationImageWidth:"500px",options:["仅I","仅II","仅III","I、II和III"],correctAnswer:0,explanation:"TCP报文段的首部格式描述了网络协议三要素中的语法（定义了数据结构和格式）、语义（定义了各字段的含义和功能）和时序（定义了报文传输的顺序和同步要求）。因此包含了所有三个要素。"}),e(a,{question:"**11.** 下列关于 OSI 参考模型的描述中，错误的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["OSI 参考模型定义了开放系统的层次结构","OSI 参考模型定义了各层所包括的可能的服务","OSI 参考模型作为一个框架协调组织各层协议的制定","OSI 参考模型定义了各层接口的实现方法"],correctAnswer:3,explanation:"OSI参考模型定义了各层的功能和层次结构，定义了各层提供的服务，并作为一个框架来协调各层协议的制定。但是，OSI参考模型并不定义各层接口的具体实现方法，它只定义了接口应该提供什么功能，而不是如何实现这些功能。接口的具体实现是由具体的协议和系统来决定的。"}),e(a,{question:"**12.** 负责将比特转换成电信号进行传输的层是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["应用层","网络层","数据链路层","物理层"],correctAnswer:3,explanation:"物理层负责将比特流转换成电信号、光信号或其他形式的信号进行传输。它定义了电气、机械、功能和规程特性，负责在通信信道上传输原始的比特流。"}),e(a,{question:"**13.** 下列关于 OSI 参考模型的物理层功能的描述中，错误的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["比特 0 和 1 使用何种电信号表示","传输能否在两个方向上同时进行","1 个比特持续多长时间","避免快速发送方‘淹没’慢速接收方"],correctAnswer:3,explanation:"避免快速发送方‘淹没’慢速接收方是数据链路层或传输层的流量控制功能，而不是物理层的功能。物理层主要负责比特流的传输，包括信号编码、传输介质、传输速率等，但不处理流量控制问题。"}),e(a,{question:"**14.** OSI参考模型中的数据链路层不具有 _______ 功能。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["物理寻址","流量控制","差错检验","拥塞控制"],correctAnswer:3,explanation:"数据链路层具有物理寻址（MAC地址）、流量控制（防止接收方被淹没）和差错检验（如CRC校验）功能。但拥塞控制是网络层和传输层的功能，数据链路层不处理网络范围的拥塞问题。"}),e(a,{question:"**15.** 下列能够最好地描述 OSI 参考模型的数据链路层功能的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["提供用户和网络的接口","处理信号通过介质的传输","控制报文通过网络的路由选择","保证数据正确的顺序和完整性"],correctAnswer:3,explanation:"数据链路层的主要功能是保证数据在相邻节点之间正确、有序地传输，包括帧同步、差错控制、流量控制等，确保数据的完整性和正确顺序。提供用户接口是应用层，信号传输是物理层，路由选择是网络层的功能。"}),e(a,{question:"**16.** 当数据由端系统 A 传送至端系统 B 时，不参与数据封装工作的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["物理层","数据链路层","网络层","表示层"],correctAnswer:0,explanation:"物理层不参与数据的封装工作，它只负责将比特流转换成信号进行传输。数据链路层添加帧头和帧尾，网络层添加IP包头，表示层负责数据格式转换和加密等封装工作。物理层是唯一不添加任何控制信息的层次。"}),e(a,{question:"**17.** 在 OSI 参考模型中，实现端到端的应答、分组排序和流量控制功能的协议层是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["会话层","网络层","传输层","数据链路层"],correctAnswer:2,explanation:"传输层负责端到端的通信，提供可靠的传输服务，包括端到端的应答机制、分组排序（保证数据按正确顺序到达）、流量控制（防止接收方被淹没）等功能。数据链路层提供的是点到点的服务，不是端到端的。"}),e(a,{question:"**18.** 在 ISO/OSI 参考模型中，可同时提供无连接服务和面向连接服务的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["物理层","数据链路层","网络层","传输层"],correctAnswer:2,explanation:"网络层可以同时提供无连接服务（如IP协议）和面向连接服务（如X.25协议）。传输层通常提供面向连接的服务（如TCP）和无连接服务（如UDP），但网络层是第一个可以同时提供这两种服务的层次。物理层和数据链路层主要提供面向连接的服务。"}),e(a,{question:"**19.** 在 OSI 参考模型中，当两台计算机进行文件传输时，为防止中间出现网络故障而重传整个文件的情况，可通过在文件中插入同步点来解决，这个动作发生在 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["表示层","会话层","网络层","应用层"],correctAnswer:1,explanation:"会话层负责建立、管理和终止会话连接，通过在数据流中插入同步点（检查点）来实现会话的恢复。当网络出现故障时，可以从最近的同步点重新开始传输，而不需要重传整个文件。"}),e(a,{question:"**20.** 数据的格式转换及压缩属于 OSI 参考模型中 _______ 的功能。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["应用层","表示层","会话层","传输层"],correctAnswer:1,explanation:"表示层负责数据的表示、转换和编码，包括数据格式转换（如ASCII到EBCDIC）、数据压缩、数据加密和解密等功能，确保不同系统间的数据能够正确解释和理解。"}),e(a,{question:"**21.** OSI参考模型中 _______ 通过设置检验点，使通信双方在通信失效时可从检验点恢复通信。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["传输层","网络层","表示层","会话层"],correctAnswer:3,explanation:"会话层通过设置同步点（检验点）来管理会话过程，当通信过程中出现故障时，可以从最近的同步点恢复通信，而不需要从头开始重新建立会话和传输数据。"}),e(a,{question:"**22.** 下列说法中正确描述了 OSI 参考模型中数据的封装过程的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["数据链路层在分组上仅增加了源物理地址和目的物理地址","网络层将高层协议产生的数据封装成分组，并增加第三层的地址和控制信息","传输层将数据流封装成数据帧，并增加可靠性和流控制信息","表示层将高层协议产生的数据分割成数据段，并增加相应的源和目的端口信息"],correctAnswer:1,explanation:"网络层负责将传输层的数据封装成分组（数据包），并添加第三层的地址（IP地址）和控制信息（如路由信息）。数据链路层添加的是帧头和帧尾（包括物理地址），传输层将数据分割成段并添加端口信息，表示层负责数据格式转换而不进行数据分割。"}),e(a,{question:"**24.** 在 OSI 参考模型中， _______ 利用通信子网提供的服务实现两个进程之间的端到端通信。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["网络层","传输层","会话层","表示层"],correctAnswer:1,explanation:"在OSI参考模型中，传输层负责利用通信子网提供的服务实现两个进程之间的端到端通信，确保数据的可靠传输。"}),e(a,{question:"**25.** 互联网采用的核心技术是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["TCP/IP","局域网技术","远程通信技术","光纤技术"],correctAnswer:0,explanation:"互联网采用的核心技术是TCP/IP协议簇，它是互联网的基础通信协议。"}),e(a,{question:"**26.** 在 TCP/IP 模型中， _______ 处理关于可靠性、流量控制和错误校正等问题。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["网络接口层","网际层","传输层","应用层"],correctAnswer:2,explanation:"在TCP/IP模型中，传输层（如TCP协议）负责处理可靠性、流量控制和错误校正等问题。"}),e(a,{question:"**27.** 上下相邻层实体之间的接口称为服务访问点，应用层的服务访问点也称 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["用户接口","网卡接口","IP地址","MAC地址"],correctAnswer:0,explanation:"在OSI参考模型中，应用层的服务访问点也称为用户接口，它是用户与网络应用交互的接口。"}),e(a,{question:"**29.** 在 OSI 参考模型中，自下而上第一个提供端到端服务的层是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["数据链路层","传输层","会话层","应用层"],correctAnswer:1,explanation:"在OSI参考模型中，自下而上第一个提供端到端服务的层是传输层，它负责进程间的端到端通信。"}),e(a,{question:"**30.** 下列选项中不属于网络体系结构所描述的内容是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["网络的层次","每层使用的协议","协议的内部实现细节","每层必须完成的功能"],correctAnswer:2,explanation:"网络体系结构描述网络的层次结构、每层使用的协议和每层必须完成的功能，但不涉及协议的具体内部实现细节。"}),e(a,{question:"**31.** 在 OSI 参考模型中，功能需由应用层的相邻层实现的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["对话管理","数据格式转换","路由选择","可靠数据传输"],correctAnswer:1,explanation:"在OSI参考模型中，表示层（应用层的相邻层）负责数据格式转换、加密解密等表示相关功能。"}),e(a,{question:"**32.** 在 OSI 参考模型中，直接为会话层提供服务的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["应用层","表示层","传输层","网络层"],correctAnswer:2,explanation:"在OSI参考模型中，传输层直接为会话层提供服务，提供可靠的端到端数据传输服务。"}),e(a,{question:"**33.** 在 OSI 参考模型中，路由器、交换机（Switch）、集线器（Hub）实现的最高功能层分别是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["2、2、1","2、2、2","3、2、1","3、2、2"],correctAnswer:2,explanation:"路由器工作在网络层（第3层），交换机工作在数据链路层（第2层），集线器工作在物理层（第1层）。"}),e(a,{question:"**34.** 假设 OSI 参考模型的应用层欲发送 400B 的数据（无拆分），除物理层和应用层外，其他各层在封装 PDU 时均引入 20B 的额外开销，则应用层的数据传输效率约为 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["80%","83%","87%","91%"],correctAnswer:0,explanation:"OSI参考模型共7层，除物理层和应用层外，其他5层（数据链路层、网络层、传输层、会话层、表示层）每层引入20B开销，总开销5×20B=100B。数据传输效率=400B/(400B+100B)=80%。"}),e(a,{question:"**35.** OSI 参考模型的第 5 层（自下而上）完成的主要功能是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["差错控制","路由选择","会话管理","数据表示转换"],correctAnswer:2,explanation:"OSI参考模型自下而上第5层是会话层，主要负责会话的建立、管理和终止，以及会话同步等功能。"}),e(a,{question:"**36.** 【2020 统考真题】下图描述的协议要素是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["仅 I","仅 II","仅 III","I、II 和 III"],correctAnswer:2,explanation:""}),e(a,{question:"**37.** 【2021统考真题】在 TCP/IP 模型中，由传输层相邻的下一层实现的主要功能是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["对话管理","路由选择","端到端报文段传输","节点到节点流量控制"],correctAnswer:1,explanation:""}),e(a,{question:"**38.** 【2022统考真题】在 ISO/OSI 参考模型中，实现两个相邻节点间流量控制功能的是 _______ 。",image:"",imageWidth:"500px",explanationImage:"",explanationImageWidth:"500px",options:["物理层","数据链路层","网络层","传输层"],correctAnswer:1,explanation:""})])}const u=_(I,[["render",g]]);export{W as __pageData,u as default};
